head.b:skin:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display&display=swap');
:root{--ink:#20231e;--paper:#fbfaf6;--cream:#f2eee6;--white:#fffefa;--clay:#b85e48;--olive:#59624f;--sage:#aab19b;--sand:#d8c8ad;--line:#d9d3c8;--muted:#706f68;--max:1220px;--shadow:0 18px 50px rgba(32,35,30,.08)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',Arial,sans-serif;font-size:16px;line-height:1.65}a{color:inherit;text-decoration:none}img{display:block;max-width:100%;height:auto}.wrap{width:min(var(--max),calc(100% - 56px));margin:0 auto}
.utility{background:var(--olive);color:#f6f3eb;font-size:11px;letter-spacing:.08em}.utility .wrap{min-height:34px;display:flex;align-items:center;justify-content:space-between}.utility-links{display:flex;gap:20px;opacity:.92}.utility-links a:hover{text-decoration:underline}
.masthead{padding:28px 0 22px;display:grid;grid-template-columns:1fr auto 1fr;align-items:end;gap:28px;border-bottom:1px solid var(--line)}.brand{justify-self:start}.brand-name{font-family:'DM Serif Display',Georgia,serif;font-size:46px;line-height:.88;letter-spacing:-.035em}.brand-sub{margin-top:10px;color:var(--muted);font-size:9px;font-weight:700;letter-spacing:.28em;text-transform:uppercase}.mast-center{justify-self:center;text-align:center;color:var(--muted);font-size:10px;letter-spacing:.15em;text-transform:uppercase}.mast-center strong{display:block;color:var(--ink);font-size:11px;letter-spacing:.09em}.mast-actions{justify-self:end;display:flex;align-items:center;gap:10px}.search{width:44px;height:44px;border:1px solid #cfc8bd;border-radius:50%;display:grid;place-items:center;font-size:19px;background:var(--white)}.cta{display:inline-flex;align-items:center;gap:10px;padding:12px 19px;background:var(--clay);color:white;border-radius:999px;font-size:12px;font-weight:700}.cta:hover{background:#a84e3b}
.mainnav{border-bottom:1px solid var(--line);background:var(--white)}.mainnav .wrap{display:flex;align-items:center;justify-content:center;gap:30px;min-height:58px}.mainnav a{position:relative;padding:18px 0 16px;font-size:13px;font-weight:600;white-space:nowrap}.mainnav a:after{content:'';position:absolute;left:0;right:100%;bottom:10px;height:2px;background:var(--clay);transition:right .2s}.mainnav a:hover:after{right:0}
.hero{padding:30px 0 12px;display:grid;grid-template-columns:minmax(0,1.72fr) minmax(300px,.88fr);gap:14px}.hero-main{position:relative;min-height:560px;overflow:hidden;background:#cfc7b9}.hero-main img{width:100%;height:100%;object-fit:cover}.hero-main:after{content:'';position:absolute;inset:35% 0 0;background:linear-gradient(180deg,transparent,rgba(18,18,14,.78))}.hero-copy{position:absolute;z-index:2;left:42px;right:40px;bottom:36px;color:#fff}.kicker{display:inline-block;padding:7px 11px;border-radius:999px;background:rgba(255,255,255,.94);color:var(--ink);font-size:10px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.hero-copy h1{max-width:760px;margin:14px 0 10px;font-family:'DM Serif Display',Georgia,serif;font-size:clamp(48px,6vw,82px);font-weight:400;line-height:.92;letter-spacing:-.035em}.hero-copy p{max-width:650px;margin:0;font-size:17px}.hero-link{display:inline-flex;margin-top:18px;padding:11px 17px;border-radius:999px;background:var(--clay);color:#fff;font-size:12px;font-weight:700}.hero-side{display:grid;grid-template-rows:1fr 1fr;gap:14px}.feature{position:relative;overflow:hidden;min-height:273px;background:#e8e0d3}.feature img{width:100%;height:100%;object-fit:cover;opacity:.78}.feature-copy{position:absolute;inset:0;padding:28px;display:flex;flex-direction:column;justify-content:flex-end;background:linear-gradient(180deg,transparent 30%,rgba(32,35,30,.72))}.feature-copy h2{margin:9px 0 7px;color:#fff;font-family:'DM Serif Display',Georgia,serif;font-size:32px;font-weight:400;line-height:.98}.feature-copy p{margin:0;color:#fff;font-size:13px;max-width:340px}.feature .kicker{width:max-content;padding:5px 9px;background:rgba(255,255,255,.9);font-size:9px}
.category-row{padding:22px 0 28px;display:grid;grid-template-columns:repeat(9,1fr);gap:18px;border-bottom:1px solid var(--line)}.cat{text-align:center}.cat-image{width:82px;height:82px;margin:0 auto 9px;border-radius:50%;overflow:hidden;border:4px solid #eee9df;background:#e8e0d3}.cat-image img{width:100%;height:100%;object-fit:cover}.cat span{font-size:12px;font-weight:600}.cat:hover .cat-image{border-color:var(--clay)}
.section{padding:48px 0 8px}.section-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:20px}.section-head h2{margin:0;font-family:'DM Serif Display',Georgia,serif;font-size:46px;font-weight:400;line-height:1}.section-head a{font-size:12px;font-weight:700;color:var(--muted)}
.latest-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.story-card{background:var(--white)}.story-image{aspect-ratio:1.18;overflow:hidden}.story-image img{width:100%;height:100%;object-fit:cover;transition:transform .35s}.story-card:hover .story-image img{transform:scale(1.03)}.story-body{padding:15px 4px 12px}.story-label{font-size:9px;font-weight:700;letter-spacing:.13em;color:var(--muted);text-transform:uppercase}.story-title{margin:7px 0 6px;font-family:'DM Serif Display',Georgia,serif;font-size:25px;line-height:1.02}.story-excerpt{margin:0;color:var(--muted);font-size:12px}
.editorial-band{margin:52px 0 14px;display:grid;grid-template-columns:1fr 1fr;background:var(--olive);color:#fff}.editorial-image{min-height:360px;background:#cfc7b9}.editorial-image img{width:100%;height:100%;object-fit:cover}.editorial-copy{padding:55px 52px;display:flex;flex-direction:column;justify-content:center}.editorial-copy .kicker{background:var(--sand);color:var(--ink);width:max-content}.editorial-copy h2{margin:15px 0 12px;font-family:'DM Serif Display',Georgia,serif;font-size:52px;font-weight:400;line-height:.95}.editorial-copy p{color:#e5e7df;max-width:470px}.editorial-copy a{width:max-content;margin-top:10px;padding:11px 17px;border:1px solid rgba(255,255,255,.55);border-radius:999px;font-size:12px;font-weight:700}
.blog-area{padding:54px 0;display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:48px}.blog-main .widget{margin:0}.post-outer{margin-bottom:52px;padding-bottom:34px;border-bottom:1px solid var(--line)}.post-title,.post-title a,.entry-title{font-family:'DM Serif Display',Georgia,serif!important;font-weight:400!important;font-size:50px!important;line-height:.98!important;letter-spacing:-.025em!important;color:var(--ink)!important}.post-body{font-family:'DM Sans',Arial,sans-serif!important;font-size:18px!important;line-height:1.8!important;color:#393b35!important}.post-body h2,.post-body h3{font-family:'DM Serif Display',Georgia,serif!important;font-weight:400!important;line-height:1.05!important}.post-body h2{font-size:38px!important}.post-body h3{font-size:29px!important}.post-body img{margin:24px 0;border-radius:3px}.sidebar-box{padding:24px;margin-bottom:18px;border-top:3px solid var(--ink);background:#f5f1e8}.sidebar-box h3{margin:0 0 12px;font-family:'DM Serif Display',Georgia,serif;font-size:28px;font-weight:400}.sidebar-box p{margin:0;color:var(--muted);font-size:13px}.sidebar-links{display:grid;gap:8px}.sidebar-links a{padding:8px 0;border-bottom:1px solid var(--line);font-size:13px;font-weight:600}.sidebar-links a:hover{color:var(--clay)}
.footer{margin-top:30px;background:var(--ink);color:#f3f0e8}.footer-top{padding:54px 0;display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:38px}.footer h3{margin:0 0 12px;font-family:'DM Serif Display',Georgia,serif;font-size:36px;font-weight:400}.footer p,.footer a{color:#bfc1b8;font-size:13px}.footer h4{margin:0 0 13px;font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:#fff}.footer-links{display:grid;gap:7px}.footer-bottom{padding:17px 0;border-top:1px solid #41443c;color:#898c83;font-size:10px;display:flex;justify-content:space-between}
@media(max-width:1050px){.mast-center{display:none}.masthead{grid-template-columns:1fr auto}.category-row{grid-template-columns:repeat(6,1fr)}.latest-grid{grid-template-columns:repeat(2,1fr)}.mainnav .wrap{gap:20px;overflow:auto;justify-content:flex-start}.editorial-band{grid-template-columns:1fr}.editorial-image{min-height:300px}.blog-area{grid-template-columns:1fr}.sidebar{display:grid;grid-template-columns:1fr 1fr;gap:18px}.sidebar-box{margin:0}}
@media(max-width:700px){.wrap{width:min(100% - 30px,var(--max))}.utility-links{display:none}.utility .wrap{justify-content:center}.masthead{padding:22px 0 18px}.brand-name{font-size:35px}.brand-sub{font-size:7px;letter-spacing:.2em}.mast-actions .search{width:38px;height:38px}.cta{padding:10px 14px}.mainnav .wrap{min-height:52px;gap:18px}.mainnav a{font-size:12px;padding:16px 0 14px}.hero{grid-template-columns:1fr;padding-top:18px}.hero-main{min-height:500px}.hero-copy{left:24px;right:22px;bottom:25px}.hero-copy h1{font-size:51px}.hero-copy p{font-size:14px}.hero-side{grid-template-columns:1fr 1fr;grid-template-rows:none}.feature{min-height:220px}.feature-copy{padding:20px}.feature-copy h2{font-size:27px}.category-row{grid-template-columns:repeat(3,1fr);gap:18px 8px}.cat-image{width:70px;height:70px}.section{padding-top:38px}.section-head h2{font-size:39px}.latest-grid{grid-template-columns:1fr}.story-title{font-size:28px}.editorial-copy{padding:38px 28px}.editorial-copy h2{font-size:43px}.sidebar{grid-template-columns:1fr}.post-title,.post-title a,.entry-title{font-size:42px!important}.post-body{font-size:17px!important}.footer-top{grid-template-columns:1fr 1fr}.footer-bottom{display:block}.footer-bottom span{display:block;margin-top:5px}}
@media(max-width:430px){.mast-actions .cta{display:none}.hero-main{min-height:470px}.hero-copy h1{font-size:46px}.hero-side{grid-template-columns:1fr}.feature{min-height:230px}.category-row{grid-template-columns:repeat(3,1fr)}.footer-top{grid-template-columns:1fr}}
